-- =====================================================================================
-- LOOKUP 4 TYPE 클라우드 이관 — SCM_ADM_LOOKUP_MASTER / SCM_ADM_LOOKUP_MASTER_DETAIL
-- 원천: 사내오라클 ZIOUI1 (SCM_MGR) 실데이터 추출 2026-10-12 10:34:26
-- 대상 LOOKUP_TYPE: DM_UI_EDITABLE_DIVISION, DM_UI_EDITABLE_MEASURE, GET_ADMIN_GROUP_MEASURE, MKT_FCST_MEASURE
-- 방식: 4 TYPE 범위 DELETE 후 INSERT (재실행 시 동일 결과 = 멱등). 타 LOOKUP_TYPE 행은 건드리지 않음.
-- 실행: 파일 전체 F5. 마지막 COMMIT 포함. 실행 계정 = SCM_MGR (테이블 소유자)
-- =====================================================================================

-- [1] DELETE — DETAIL(자식) 먼저, MASTER(부모) 다음
DELETE FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE IN ('DM_UI_EDITABLE_DIVISION','DM_UI_EDITABLE_MEASURE','GET_ADMIN_GROUP_MEASURE','MKT_FCST_MEASURE');
DELETE FROM SCM_ADM_LOOKUP_MASTER        WHERE LOOKUP_TYPE IN ('DM_UI_EDITABLE_DIVISION','DM_UI_EDITABLE_MEASURE','GET_ADMIN_GROUP_MEASURE','MKT_FCST_MEASURE');

-- [2] INSERT SCM_ADM_LOOKUP_MASTER (4 rows)

-- [2] INSERT SCM_ADM_LOOKUP_MASTER_DETAIL (225 rows)

COMMIT;

-- [3] 검증 — 기대 건수: M DM_UI_EDITABLE_DIVISION=1 / M DM_UI_EDITABLE_MEASURE=1 / M GET_ADMIN_GROUP_MEASURE=1 / M MKT_FCST_MEASURE=1 / D DM_UI_EDITABLE_DIVISION=5 / D DM_UI_EDITABLE_MEASURE=26 / D GET_ADMIN_GROUP_MEASURE=170 / D MKT_FCST_MEASURE=24
SELECT 'MASTER' TBL, LOOKUP_TYPE, COUNT(*) CNT FROM SCM_ADM_LOOKUP_MASTER WHERE LOOKUP_TYPE IN ('DM_UI_EDITABLE_DIVISION','DM_UI_EDITABLE_MEASURE','GET_ADMIN_GROUP_MEASURE','MKT_FCST_MEASURE') GROUP BY LOOKUP_TYPE
UNION ALL
SELECT 'DETAIL', LOOKUP_TYPE, COUNT(*) FROM SCM_ADM_LOOKUP_MASTER_DETAIL WHERE LOOKUP_TYPE IN ('DM_UI_EDITABLE_DIVISION','DM_UI_EDITABLE_MEASURE','GET_ADMIN_GROUP_MEASURE','MKT_FCST_MEASURE') GROUP BY LOOKUP_TYPE ORDER BY 1 DESC, 2;
